input.command:
.venv/bin/python -I -c "
import json,glob,os
rows=[]
for f in sorted(glob.glob('logs/sessions/practice/*.json')):
    d=json.load(open(f)); r=d.get('result') or {}
    cb=r.get('cost_breakdown') or {}
    cd=r.get('c_deal'); cbst=r.get('c_best')
    s=sum(cb.values()) if cb else None
    rows.append((os.path.basename(f)[:-5], d.get('case_id'), d.get('end_reason'), r.get('deal'), round(r.get('score') or 0,3) if r.get('score') is not None else None, round(r.get('c_open') or 0), round(cd) if cd else None, round(r.get('c_alt') or 0) if r.get('c_alt') else None, round(cbst) if cbst else None, round(cd-cbst) if cd and cbst else None, round(s-cd) if (s and cd) else None, {k:round(v) for k,v in cb.items() if v}, r.get('must_haves_ok')))
for x in rows: print(x)
print(len(rows))
"

